			},
			wantErr:        false,
			checkTemplate:  true,
			expectedString: `--control-plane-endpoint="${KUBEADM_NODE_IP}:6443"`,
			checkSafeExit:  true,
		},
		{
			name: "kind installer",
			env: v1alpha1.Environment{
				Spec: v1alpha1.EnvironmentSpec{
